  --radius-badge: calc(var(--spacing) * 1);
  --radius-field: calc(var(--spacing) * 2);
  --radius-card: calc(var(--spacing) * 4);
  --radius-chart-radial: calc(var(--spacing) * 1);
  --radius-chart-bar: calc(var(--spacing) * 1.5);

  /* ─── Layout / Size ────────────────────────────────────────────────────── */
  --spacing-badge: calc(var(--spacing) * 8);
  --spacing-field: calc(var(--spacing) * 9);
  --spacing-card: calc(var(--spacing) * 12);

  /* ─── Layout / Gap ─────────────────────────────────────────────────────── */
  --gap-badge: calc(var(--spacing) * 0.5);
  --gap-field: calc(var(--spacing) * 1);
  --gap-card: calc(var(--spacing) * 2);

  /* ─── Layout / Padding ─────────────────────────────────────────────────── */
  --padding-xs: calc(var(--spacing) * 0.5);
  --padding-sm: calc(var(--spacing) * 1);
  --padding-badge: calc(var(--spacing) * 1.5);
  --padding-field: calc(var(--spacing) * 2);
  --padding-card: calc(var(--spacing) * 3);

  /* ─── Elevation ────────────────────────────────────────────────────────── */
  --shadow-xs: 0 1px 2px 0 var(--black-a1);
  --shadow-sm: 0 1px 2px 0 var(--black-a1), 0 1px 3px 0 var(--black-a1);
  --shadow-md: 0 2px 4px -2px var(--black-a1), 0 4px 8px -2px var(--black-a2);
  --shadow-lg: 0 4px 6px -2px var(--black-a1), 0 12px 16px -4px var(--black-a2);
  --shadow-xl: 0 8px 8px -4px var(--black-a1), 0 20px 24px -4px var(--black-a2);
  --shadow-2xl: 0 24px 48px -12px var(--black-a4);
  --shadow-3xl: 0 32px 64px -12px var(--black-a3);

  /* ─── Motion / Duration ────────────────────────────────────────────────── */
  --duration-fast: 100ms;
  --duration-normal: 200ms;
  --duration-slow: 300ms;
  --duration-slower: 500ms;

  /* ─── Motion / Easing ──────────────────────────────────────────────────── */
  --ease-enter: cubic-bezier(0, 0, 0.2, 1);
  --ease-exit: cubic-bezier(0.4, 0, 1, 1);
  --ease-standard: cubic-bezier(0.4, 0, 0.2, 1);
  --ease-emphasized: cubic-bezier(0.16, 1, 0.3, 1);

  /* ─── Motion / Animation ───────────────────────────────────────────────── */
  --animate-accordion-down: accordion-down var(--duration-normal) var(--ease-enter);
  --animate-accordion-up: accordion-up var(--duration-normal) var(--ease-enter);
  --animate-overlay-in: overlay-in var(--duration-normal) var(--ease-enter);
  --animate-overlay-out: overlay-out var(--duration-fast) var(--ease-exit);
  --animate-dialog-in: dialog-in var(--duration-normal) var(--ease-enter);
  --animate-dialog-out: dialog-out var(--duration-fast) var(--ease-exit);
  --animate-popover-in: popover-in var(--duration-fast) var(--ease-enter);
  --animate-popover-out: popover-out var(--duration-fast) var(--ease-exit);
  --animate-sheet-in: sheet-in var(--duration-slow) var(--ease-enter);
  --animate-sheet-out: sheet-out var(--duration-normal) var(--ease-exit);
}

/* ============================================================================
