  --text-title-1: var(--solar-type-medium-4);
  --text-title-2: var(--solar-type-medium-5);
  --text-title-3: var(--solar-type-medium-6);
  --text-title-4: var(--solar-type-medium-7);
  --text-title-5: var(--solar-type-medium-8);
  --text-title-6: var(--solar-type-medium-9);
  --text-label: var(--solar-type-medium-10);
  --text-label-compact: var(--solar-type-medium-11);
  --text-body: var(--solar-type-medium-9);
  --text-body-compact: var(--solar-type-medium-10);
