/* ============================================================================
 * SolarUI — mécanique du mouvement
 * ----------------------------------------------------------------------------
 * Les FORMES des animations : keyframes, et le vecteur de glissement déduit de
 * `data-side`. Aucune valeur de temps ni de courbe ici — durées et easings sont
 * des variables Figma et vivent dans themes/*.css, tout comme les `--animate-*`
 * qui assemblent forme, durée et courbe.
 *
 * Ce découpage a une raison : un thème peut retimer toute l'interface sans
 * toucher à ce fichier, et une keyframe ajoutée ici profite à tous les thèmes.
 * ========================================================================== */

/* ─── Direction du glissement ─────────────────────────────────────────────────
 * Radix pose `data-side` tout seul sur les contenus ancrés, et sheet le porte
 * aussi. Un composant n'a donc QUE deux classes à écrire — `animate-popover-in`
 * et `animate-popover-out` — au lieu des quatorze que shadcn empile.
 *
 * Convention : le vecteur pointe vers le côté nommé. Sheet glisse depuis ce
 * côté ; popover fait l'inverse et s'écarte de sa cible, d'où le signe négatif
 * dans ses keyframes.
 * -------------------------------------------------------------------------- */

[data-side="top"]    { --solar-dir-x: 0;  --solar-dir-y: -1; }
[data-side="bottom"] { --solar-dir-x: 0;  --solar-dir-y: 1; }
[data-side="left"]   { --solar-dir-x: -1; --solar-dir-y: 0; }
[data-side="right"]  { --solar-dir-x: 1;  --solar-dir-y: 0; }

@keyframes accordion-down {
  from { height: 0; }
  to   { height: var(--radix-accordion-content-height); }
}

@keyframes accordion-up {
  from { height: var(--radix-accordion-content-height); }
  to   { height: 0; }
}

@keyframes overlay-in  { from { opacity: 0; } to { opacity: 1; } }
@keyframes overlay-out { from { opacity: 1; } to { opacity: 0; } }

@keyframes dialog-in {
  from { opacity: 0; transform: scale(0.95); }
  to   { opacity: 1; transform: scale(1); }
}

@keyframes dialog-out {
  from { opacity: 1; transform: scale(1); }
  to   { opacity: 0; transform: scale(0.95); }
}

@keyframes popover-in {
  from {
    opacity: 0;
    transform: scale(0.95)
      translate(calc(var(--solar-dir-x, 0) * -0.5rem), calc(var(--solar-dir-y, 0) * -0.5rem));
  }
  to { opacity: 1; transform: scale(1) translate(0, 0); }
}

@keyframes popover-out {
  from { opacity: 1; transform: scale(1) translate(0, 0); }
  to {
    opacity: 0;
    transform: scale(0.95)
      translate(calc(var(--solar-dir-x, 0) * -0.5rem), calc(var(--solar-dir-y, 0) * -0.5rem));
  }
}

@keyframes sheet-in {
  from {
    opacity: 0;
    transform: translate(calc(var(--solar-dir-x, 0) * 2.5rem), calc(var(--solar-dir-y, 0) * 2.5rem));
  }
  to { opacity: 1; transform: translate(0, 0); }
}

@keyframes sheet-out {
  from { opacity: 1; transform: translate(0, 0); }
  to {
    opacity: 0;
    transform: translate(calc(var(--solar-dir-x, 0) * 2.5rem), calc(var(--solar-dir-y, 0) * 2.5rem));
  }
}

/* ============================================================================
 * SolarUI — styles de base
 * ----------------------------------------------------------------------------
 * Ce que le design system impose au document lui-même, avant tout composant.
 * Uniquement des tokens du thème actif : ce fichier suit `data-theme` sans
 * traitement particulier.
 * ========================================================================== */

@layer base {
  * {
    border-color: var(--color-default-6);
  }

  body {
    background-color: var(--color-default-1);
    color: var(--color-default-12);
    font-family: var(--font-body);
  }

  button:not(:disabled),
  [role="button"]:not(:disabled) {
    cursor: pointer;
  }

  /* ─── Input gradient border ─────────────────────────────────────────────── */
  [data-slot="input"] {
    background:
      linear-gradient(to top, var(--color-default-2), var(--color-default-1)) padding-box,
      linear-gradient(to bottom, var(--color-default-8), var(--color-default-6)) border-box;
    border-color: transparent;
  }

  [data-slot="input"]:disabled {
    background: var(--color-default-3);
  }

  [data-slot="input"]:focus-visible {
    background:
      linear-gradient(to top, var(--color-default-2), var(--color-default-1)) padding-box,
      linear-gradient(to bottom, var(--color-default-9), var(--color-default-8)) border-box;
  }

  [data-slot="input"][aria-invalid="true"] {
    background:
      linear-gradient(to top, var(--color-default-2), var(--color-default-1)) padding-box,
      linear-gradient(to bottom, var(--color-error-7), var(--color-error-7)) border-box;
  }
}

/* ============================================================================
 * SolarUI — point d'entrée du design system
 * ----------------------------------------------------------------------------
 * Seul fichier à importer dans votre CSS applicatif :
 *
 *     @import "tailwindcss";
 *     @import "./theme.css";
 *
 * Il n'assemble que des imports. Chaque fichier a une responsabilité unique :
 *
 *     radix.css    couleurs primitives Radix + variante `dark`   (Figma « Mode »)
 *     screen.css   espacement et gammes typographiques           (Figma « Screen »)
 *     themes/*.css tous les tokens sémantiques                   (Figma « Theme »)
 *     motion.css   keyframes et vecteurs de glissement           (hors Figma)
 *     base.css     styles imposés au document
 *
 * Trois axes indépendants se combinent librement :
 *   • clair / sombre     → classe `.dark` sur <html>
 *   • desktop / mobile   → automatique, breakpoint 48rem
 *   • thème              → attribut `data-theme` sur <html>
 * ========================================================================== */

@import "./radix.css";
@import "./screen.css";

/* ─── Thèmes ──────────────────────────────────────────────────────────────────
 * Tous les thèmes importés sont disponibles à tout moment via
 * `<html data-theme="…">`.
 *
 * L'ORDRE DE CES LIGNES N'A AUCUNE IMPORTANCE. Turbopack réordonne les `@import`
 * entre `next dev` et `next build` : s'appuyer sur l'ordre donnerait un thème
 * par défaut différent selon le mode. Le thème par défaut est donc désigné DANS
 * son propre fichier, par la FORME de son bloc :
 *   • le défaut s'écrit `@theme { … }`  — il DÉCLARE les noms auprès de Tailwind
 *     et fournit les valeurs par défaut ;
 *   • les autres s'écrivent `:root[data-theme="…"] { … }` — valeurs seules.
 *
 * Tailwind range `@theme` dans `@layer theme` ; une règle non-layered l'emporte
 * toujours sur une règle layered, donc `data-theme` bat le défaut quel que soit
 * l'ordre des imports. Un simple `:root { --color-brand-9: … }` chez vous le bat
 * aussi, sans `!important`.
 *
 * Défaut actuel : Stellar → themes/stellar.css
 * ------------------------------------------------------------------------- */

@import "./themes/stellar.css";
@import "./themes/trevia.css";

@import "./motion.css";
@import "./base.css";

/* ============================================================================
 * Schéma d'un thème
 * ----------------------------------------------------------------------------
 * Les 185 tokens qu'un thème peut porter. Généré depuis themes/stellar.css :
 * toute divergence est un bug.
 *
 * À copier dans votre CSS pour surcharger le thème actif — retirez le préfixe
 * « * », et ne gardez que ce que vous redéfinissez : tout token omis conserve la
 * valeur du thème par défaut. Les intertitres « ── … ── » sont des repères de
 * lecture, pas du CSS. Les pièges de nommage sont documentés en tête de
 * themes/stellar.css.
 *
 *   :root[data-theme="mon-theme"] {
 *     --color-brand-9: var(--violet-9);
 *   }
 *
 *   ── Palette / Default ──
 *   --color-default-1: ;
 *   --color-default-2: ;
 *   --color-default-3: ;
 *   --color-default-4: ;
